Hi, ggplot2 is definitely compatible with Sweave, I use them together<br>all the time. There are some tricks, though. The easiest way I&#39;ve<br>found to use ggplot is to do something like the following:<p>&lt;&lt;results=tex&gt;&gt;=<p>plot &lt;- ggplot(...) + etc<p>ggsave.latex(plot, width=5, heigh=5, floating=FALSE,<br>filename=&quot;myggplot.pdf&quot;)<br>@<p>Where ggsave.latex is (courtesy of Thierry Onkelinkx):<p># <a href="https://stat.ethz.ch/pipermail/r-help/2009-January/183960.html" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=https://stat.ethz.ch/pipermail/r-help/2009-January/183960.html&amp;source=gmail&amp;ust=1792383968497000&amp;usg=AOvVaw2W5E_reWRz2aGnTdbY2Nk9">https://stat.ethz.ch/pipermail/r-help/2009-January/183960.html</a><br>ggsave.latex &lt;- function(..., caption = NULL, label = NULL,<br>figure.placement = &quot;hbt&quot;, floating = TRUE, caption.placement=&quot;bottom&quot;,<br>latex.environments=&quot;center&quot;){<br>	ggsave(...)<p>	cat(&quot;

&quot;)<br>	if(floating){<br>		cat(&quot;\begin{figure}[&quot;, figure.placement, &quot;]
&quot;, sep = &quot;&quot;)<br>	}<br>	cat(&quot;    \begin{&quot;, latex.environments,&quot;}
&quot;, sep = &quot;&quot;)<br>	if(!is.null(caption) &amp;&amp; caption.placement == &quot;top&quot;){<br>		cat(&quot;        \caption{&quot;, caption, &quot;}
&quot;, sep = &quot;&quot;)<br>	}<br>	args &lt;- list(...)<br>	if(is.null(args[[&quot;filename&quot;]])){<br>		if(is.null(args[[&quot;path&quot;]])){<br>			args[[&quot;path&quot;]] &lt;- &quot;&quot;<br>		}<br>		if(is.null(args[[&quot;plot&quot;]])){<br>			names(args)[which(names(args) == &quot;&quot;)[1]] &lt;- &quot;plot&quot;<br>		}<br>		args[[&quot;filename&quot;]] &lt;- paste(args[[&quot;path&quot;]],<br>digest.ggplot(args[[&quot;plot&quot;]]), &quot;.pdf&quot;, sep=&quot;&quot;)<br>	}<p>	if(is.null(args[[&quot;width&quot;]])){<br>		if(is.null(args[[&quot;height&quot;]])){<br>			cat(&quot;        \includegraphics[height = 7in, width = 7in]{&quot;,<br>args[[&quot;filename&quot;]], &quot;}
&quot;, sep = &quot;&quot;)<br>		} else {<br>			cat(&quot;        \includegraphics[height = &quot;, args[[&quot;height&quot;]], &quot;in,<br>width = 7in]{&quot;, args[[&quot;filename&quot;]], &quot;}
&quot;, sep = &quot;&quot;)<br>		}<br>	} else {<br>		if(is.null(args[[&quot;height&quot;]])){<br>			cat(&quot;        \includegraphics[height = 7in, width = &quot;,<br>args[[&quot;width&quot;]], &quot;in]{&quot;, args[[&quot;filename&quot;]], &quot;}
&quot;, sep = &quot;&quot;)<br>		} else {<br>			cat(&quot;        \includegraphics[height = &quot;, args[[&quot;height&quot;]], &quot;in,<br>width = &quot;, args[[&quot;width&quot;]], &quot;in]{&quot;, args[[&quot;filename&quot;]], &quot;}
&quot;, sep =<br>&quot;&quot;)<br>		}<br>	}<br>	if(!is.null(caption) &amp;&amp; caption.placement == &quot;bottom&quot;){<br>		cat(&quot;        \caption{&quot;, caption, &quot;}
&quot;, sep = &quot;&quot;)<br>	}<br>	if(!is.null(label)){<br>		cat(&quot;        \label{&quot;, label, &quot;}
